CREATE TYPE public.app_role AS ENUM ('harel','rami');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE FUNCTION public.assign_noa_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL THEN IF lower(NEW.email)='harel@saban94.co.il' THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'harel') ON CONFLICT DO NOTHING; ELSIF lower(NEW.email)='ramims@saban94.co.il' THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'rami') ON CONFLICT DO NOTHING; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER noa_verified_role AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_noa_role();
CREATE TABLE public.noa_trips (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requested_by uuid NOT NULL, driver_id uuid, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','sharing','stopped','declined')), destination text NOT NULL, arrival_time text NOT NULL DEFAULT '', waze_url text NOT NULL DEFAULT '', latitude double precision, longitude double precision, accuracy double precision, location_updated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), consented_at timestamptz, stopped_at timestamptz);
GRANT SELECT,INSERT,UPDATE ON public.noa_trips TO authenticated; GRANT ALL ON public.noa_trips TO service_role;
ALTER TABLE public.noa_trips ENABLE ROW LEVEL SECURITY;
CREATE POLICY trip_read ON public.noa_trips FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'harel') OR public.has_role(auth.uid(),'rami'));
CREATE POLICY trip_request ON public.noa_trips FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'harel') AND requested_by=auth.uid() AND status='requested' AND driver_id IS NULL AND latitude IS NULL AND longitude IS NULL);
CREATE POLICY trip_consent ON public.noa_trips FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'rami') AND (driver_id IS NULL OR driver_id=auth.uid())) WITH CHECK(public.has_role(auth.uid(),'rami') AND driver_id=auth.uid());
CREATE TABLE public.noa_devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, token text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.noa_devices TO authenticated; GRANT ALL ON public.noa_devices TO service_role;
ALTER TABLE public.noa_devices ENABLE ROW LEVEL SECURITY;
CREATE POLICY device_own ON public.noa_devices FOR ALL TO authenticated USING(user_id=auth.uid() AND (public.has_role(auth.uid(),'harel') OR public.has_role(auth.uid(),'rami'))) WITH CHECK(user_id=auth.uid() AND (public.has_role(auth.uid(),'harel') OR public.has_role(auth.uid(),'rami')));
CREATE TABLE public.noa_delivery_writes (id uuid PRIMARY KEY, user_id uuid NOT NULL, note_number text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', sheet_row text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.noa_delivery_writes TO authenticated; GRANT ALL ON public.noa_delivery_writes TO service_role;
ALTER TABLE public.noa_delivery_writes ENABLE ROW LEVEL SECURITY;
CREATE POLICY delivery_roles ON public.noa_delivery_writes FOR ALL TO authenticated USING(public.has_role(auth.uid(),'harel') OR public.has_role(auth.uid(),'rami')) WITH CHECK(user_id=auth.uid() AND (public.has_role(auth.uid(),'harel') OR public.has_role(auth.uid(),'rami')));